head.script:
scwin.testFormatter = function(param) {
    return '[ ' + param + ' ]';
};
scwin.test2Formatter = function(param) {
    return '** ' + param + ' **';
};
scwin.customFormatter = function(data, formattedData, rowIndex, colIndex) {
    return '*** ' + data + ' ***';
};
scwin.customFormatter2 = function(data, formattedData, rowIndex, colIndex) {
    return '[[ ' + data + ' ]]';
};
scwin.init = function() {
    grd.setData(dataList1.getAllData());
    grd.setCellBackgroundColor(2, 2, "yellow");
    grd.setCellInputType(2, 2, {
        inputType: 'text',
        options: {
            customFormatter: "scwin.customFormatter"
        },
        value: "0123테스트456"
    });
};
scwin.trigger1_onclick = function(e) {
    //debugger;
    grd.setCellDisplayFormatter(2, 2, "scwin.test2Formatter");
};
scwin.trigger2_onclick = function(e) {
    grd.setCellCustomFormatter(2, 2, "scwin.customFormatter2");
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#grd_cell_2_2').text() == '[[ 0123테스트456 ]]';
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd_cell_2_2').text()", "*** 0123테스트456 ***");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 'setCellCustomFormatter( 2, 2, "scwin.customFormatter2" );' 버튼을 클릭한다.
    //1.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 2. '[[0123테스트456]]' 값이 보여진다.(기능추가건임)
    //2. value is '[[0123테스트456]]'
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest
    //Created By: Sang.do
    //Created By: 19-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
